def P(t,s="BodyX"): return Paragraph(t,S[s])
def bullet(t): return P("<font color='#08786C'><b>•</b></font>  "+t)
def tbl(head,rows,widths):
 data=[[P(str(x),"TH") for x in head]]+[[P(str(x),"TB") for x in row] for row in rows]
 t=Table(data,colWidths=widths,repeatRows=1,hAlign="LEFT")
 t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),NAVY2),("ROWBACKGROUNDS",(0,1),(-1,-1),[WHITE,PAPER]),("GRID",(0,0),(-1,-1),.45,LINE),("VALIGN",(0,0),(-1,-1),"TOP"),("LEFTPADDING",(0,0),(-1,-1),6),("RIGHTPADDING",(0,0),(-1,-1),6),("TOPPADDING",(0,0),(-1,-1),5),("BOTTOMPADDING",(0,0),(-1,-1),5)]))
 return t
def card(title,body,width,fill=WHITE):
 t=Table([[[P(title,"CH"),P(body,"CB")]]],colWidths=[width])
 t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),fill),("BOX",(0,0),(-1,-1),.6,LINE),("ROUNDEDCORNERS",[6,6,6,6]),("VALIGN",(0,0),(-1,-1),"TOP"),("LEFTPADDING",(0,0),(-1,-1),9),("RIGHTPADDING",(0,0),(-1,-1),9),("TOPPADDING",(0,0),(-1,-1),8),("BOTTOMPADDING",(0,0),(-1,-1),8)]))
 return t
def note(title,body,width,fill=PALE,accent=TEAL):
 t=Table([[P(f"<b>{title}</b><br/>{body}","Call")]],colWidths=[width])
 t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),fill),("LINEBEFORE",(0,0),(0,0),3,accent),("LEFTPADDING",(0,0),(-1,-1),10),("RIGHTPADDING",(0,0),(-1,-1),9),("TOPPADDING",(0,0),(-1,-1),7),("BOTTOMPADDING",(0,0),(-1,-1),7)]))
 return t
def cover(c,doc):
 w,h=A4;c.saveState();c.setFillColor(NAVY);c.rect(0,0,w,h,fill=1,stroke=0);c.setFillColor(colors.HexColor("#183746"));c.circle(w*.92,h*.93,120*mm,fill=1,stroke=0);c.setFillColor(NAVY);c.rect(0,0,w*.70,h,fill=1,stroke=0);c.restoreState()
def footer(c,doc):
 w,h=A4;c.saveState();c.setFillColor(NAVY);c.setFont(B,7);c.drawString(19*mm,h-13*mm,"KAGEFLOW");c.setFillColor(MUTED);c.setFont(R,7);c.drawRightString(w-19*mm,h-13*mm,"System overview");c.setStrokeColor(LINE);c.setLineWidth(.45);c.line(19*mm,h-16*mm,w-19*mm,h-16*mm);c.line(19*mm,15*mm,w-19*mm,15*mm);c.setFillColor(MUTED);c.setFont(R,6.8);c.drawString(19*mm,10*mm,"Kageflow · Pretan Technologies · System overview");c.drawRightString(w-19*mm,10*mm,f"Page {doc.page-1} of 10");c.restoreState()
class Doc(BaseDocTemplate):
 def __init__(self,fn):
  super().__init__(fn,pagesize=A4,leftMargin=19*mm,rightMargin=19*mm,topMargin=22*mm,bottomMargin=20*mm,title="Kageflow System Overview",author="Pretan Technologies")
  a=Frame(19*mm,18*mm,A4[0]-38*mm,A4[1]-36*mm,leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0,id="cover")
  b=Frame(19*mm,20*mm,A4[0]-38*mm,A4[1]-42*mm,leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0,id="body")
  self.addPageTemplates([PageTemplate(id="cover",frames=a,onPage=cover),PageTemplate(id="body",frames=b,onPage=footer)])
 def afterPage(self):
  if self.page==1:self.handle_nextPageTemplate("body")
