cards.setStyle(TableStyle([("VALIGN",(0,0),(-1,-1),"TOP"),("LEFTPADDING",(0,0),(-1,-1),0),("RIGHTPADDING",(0,0),(-1,-1),4*mm),("TOPPADDING",(0,0),(-1,-1),0),("BOTTOMPADDING",(0,0),(-1,-1),0)]))
story += [cards,Spacer(1,5*mm),P("The dealership cycle","H2X"),tbl(["STAGE","WHAT HAPPENS"],[("Acquire","Create or import the vehicle; record supplier, purchase and arrival details."),("Prepare and advertise","Add vehicle costs, photos and advert details; publish selected stock to feeds or the website."),("Capture demand","Bring buyer enquiries in from connected channels or enter them manually."),("Work the opportunity","Qualify the lead, follow up, progress a deal, issue a quote and confirm an order."),("Complete the sale","Issue the invoice, apply deposits and other payments, account for the vehicle cost and tax."),("Review","Reconcile banking, check reports and use results to guide stock and sales decisions.")],[36*mm,W-36*mm]),Spacer(1,4*mm),note("The central idea","The vehicle is a useful anchor: purchase and running costs, advertising, buyer enquiries, deal and final sale can be traced through one system record.",W),PageBreak()]

