story += [P("STOCK","Kick"),P("A complete record for each vehicle","TitleX"),P("Kageflow follows vehicles from identification and acquisition through preparation, advertising, reservation and sale. Costs accumulate against the unit to help the dealership understand stock position and eventual result.","DeckX"),tbl(["FUNCTION","WHAT IT DOES"],[("Create or import","Add a vehicle with VIN and details; scan a VIN on supported devices or import rows from a spreadsheet."),("Identify and track","Use the stock number and VIN as references; track whether the unit is in transit, in stock, reserved, sold or otherwise unavailable."),("Record landed costs","Attach purchase, transport, clearing, duty, repairs, recon and other costs. Owed costs can create supplier bills."),("Prepare the advert","Store customer-facing description, headline, price, features and photos; choose a lead photo."),("Publish","Publish selected vehicles to stock feeds and connected website channels. Reserved or sold vehicles can be removed from public availability."),("Check the lot","Scan VINs and compare expected stock with vehicles physically found."),("Work with dealers","Receive shared listings or accept incoming vehicle transfers from other Kageflow dealerships.")],[38*mm,W-38*mm]),Spacer(1,5*mm),P("One vehicle, connected records","H2X"),P("A unit can link to costs, suppliers, photos, enquiries, deals, quotes, orders, finance applications, trade-ins, invoices and stock movements. This gives the team a traceable vehicle history.","BodyX"),note("Supplier-listed vehicles","A vehicle advertised on a supplier's floor can be listed without treating it as owned stock. It enters the dealership's stock and books when the dealer buys it.",W),PageBreak()]

